select cron.schedule('ads-balance-guard-every-5min','*/5 * * * *', $$select net.http_post(url:='https://oicqtpjjwmgsiluvkmpu.supabase.co/functions/v1/ads-manager', headers:=jsonb_build_object('Content-Type','application/json','x-cron-secret',(select value from public.app_secrets where key='ads_cron_secret')), body:='{"action":"balance_guard"}'::jsonb, timeout_milliseconds:=120000)$$);
